#!/usr/bin/env python3
"""OpenSTA static timing analysis driver.

Reads the gate level netlist produced by run_synth.py, applies a simple but
realistic constraint set (single clock, 20 % input/output external delay,
bounded input transition and output load) and reports setup and hold slack.

A negative worst slack fails the run, so timing regressions are caught by
``ctest`` in exactly the same way as functional regressions.
"""
from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path

STA_SCRIPT = """\
# Auto-generated by run_sta.py - do not edit.
read_liberty {liberty}
read_verilog {netlist}
link_design {top}

# --- clock -----------------------------------------------------------------
create_clock -name {clock} -period {period} [get_ports {{{clock}}}]
# Setup and hold get different margins. The clock is ideal (pre-layout, no
# clock tree), so the setup margin stands in for jitter plus the skew a real
# tree will add, while the hold margin may only model what an ideal clock can
# genuinely be off by. Applying the setup figure to hold fails every register
# that feeds itself through a gate or two - which is every counter - on
# pessimism that clock-tree synthesis and hold fixing exist to resolve.
set_clock_uncertainty -setup {setup_uncertainty} [get_clocks {clock}]
set_clock_uncertainty -hold  {hold_uncertainty} [get_clocks {clock}]
set_clock_transition {transition} [get_clocks {clock}]

# --- I/O environment -------------------------------------------------------
# OpenSTA returns object lists, not Synopsys collections: there is no
# remove_from_collection or sizeof_collection, so the clock is excluded with
# -no_clocks and the lists are counted with llength.
set _inputs  [all_inputs -no_clocks]
set _outputs [all_outputs]

if {{[llength $_inputs] > 0}} {{
  set_input_delay  -clock {clock} {io_delay} $_inputs
  set_input_transition {transition} $_inputs
}}
if {{[llength $_outputs] > 0}} {{
  set_output_delay -clock {clock} {io_delay} $_outputs
  set_load {load} $_outputs
}}
{sdc_block}
# --- reports ---------------------------------------------------------------
puts "=== setup (max) ==="
report_checks -path_delay max -group_path_count 5 -digits 4
puts "=== hold (min) ==="
report_checks -path_delay min -group_path_count 5 -digits 4
puts "=== summary ==="
report_worst_slack -max -digits 4
report_worst_slack -min -digits 4
report_tns -digits 4
report_check_types -violators -digits 4
puts "=== clocks ==="
report_clock_properties
exit
"""

# The block's own constraint fragment, sourced the way an integrator would,
# with the instance name empty: the block is the top of the design. A Tcl
# error in it - an unknown command above all, which is how a Synopsys-only
# command shows up - fails the run instead of leaving a fragment that has
# never been executed by any tool.
SDC_BLOCK = """
# --- the block's own constraint fragment -----------------------------------
set {prefix}_INST ""
if {{[catch {{source {sdc}}} _err]}} {{
  puts "SDC FAILED: $_err"
  exit
}}
"""

# OpenSTA prints "worst slack max 6.8641" / "worst slack min 0.0821"; older
# releases omitted the max/min word. Both forms must match: a pattern that
# misses them finds no slack at all, and an empty result is treated below as
# "no timing endpoints", which passes - so a mismatch here would silently pass
# every design, violations included.
SLACK_RE = re.compile(r"worst slack(?:\s+(?:max|min))?\s+(-?[0-9.]+)",
                      re.IGNORECASE)

# Registered designs always print both worst-slack lines. Seeing a register in
# the netlist and no slack in the log means the log format changed, which must
# fail loudly rather than be mistaken for a combinational design.
REGISTER_RE = re.compile(r"\b(DFF\w*|SDFF\w*|LATCH\w*)\b")


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--sta", default="sta")
    p.add_argument("--top", required=True)
    p.add_argument("--name", required=True)
    p.add_argument("--netlist", required=True)
    p.add_argument("--liberty", required=True)
    p.add_argument("--period", type=float, default=10.0, help="clock period in ns")
    p.add_argument("--clock", default="clk")
    p.add_argument("--out-dir", required=True)
    p.add_argument("--report", required=True)
    p.add_argument("--sdc", help="the block's constraint fragment to source")
    return p.parse_args()


def main() -> int:
    args = parse_args()

    netlist = Path(args.netlist)
    if not netlist.is_file():
        sys.stderr.write(
            f"STA SKIPPED: {args.name} has no netlist at {netlist}; run synthesis first\n")
        return 1

    out_dir = Path(args.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    report = Path(args.report)
    report.parent.mkdir(parents=True, exist_ok=True)

    sdc_block = ""
    if args.sdc:
        sdc = Path(args.sdc).resolve()
        sdc_block = SDC_BLOCK.format(prefix=sdc.stem.upper(), sdc=sdc)

    script = STA_SCRIPT.format(
        sdc_block=sdc_block,
        liberty=Path(args.liberty).resolve(),
        netlist=netlist.resolve(),
        top=args.top,
        clock=args.clock,
        period=f"{args.period:.4f}",
        setup_uncertainty=f"{args.period * 0.05:.4f}",
        hold_uncertainty="0.0500",
        transition="0.100",
        io_delay=f"{args.period * 0.20:.4f}",
        load="0.010",
    )
    script_path = out_dir / f"{args.name}.sta.tcl"
    script_path.write_text(script, encoding="utf-8")

    proc = subprocess.run(
        [args.sta, "-no_splash", "-exit", str(script_path)],
        capture_output=True, text=True)
    log = proc.stdout + proc.stderr
    report.write_text(
        f"# OpenSTA: {args.name} (top={args.top}, period={args.period} ns)\n\n{log}",
        encoding="utf-8")

    if proc.returncode != 0:
        sys.stderr.write(log)
        sys.stderr.write(f"\nSTA FAILED: {args.name} (tool error)\n")
        return 1

    if "SDC FAILED" in log:
        sys.stderr.write(log)
        sys.stderr.write(f"\nSTA FAILED: {args.name} constraint fragment {args.sdc}\n")
        return 1

    slacks = [float(m) for m in SLACK_RE.findall(log)]
    if not slacks:
        if REGISTER_RE.search(netlist.read_text(encoding="utf-8", errors="replace")):
            sys.stderr.write(log)
            sys.stderr.write(
                f"\nSTA FAILED: {args.name} has registers but no worst slack "
                "was found in the OpenSTA log; the report format is not the "
                "one this driver parses\n")
            return 1
        # A purely combinational design with no registers yields no clocked
        # endpoints; that is a valid, non-failing outcome.
        print(f"STA PASS: {args.name} (no timing endpoints to report)")
        return 0

    worst = min(slacks)
    if worst < 0.0:
        sys.stderr.write(log)
        sys.stderr.write(
            f"\nSTA FAILED: {args.name} worst slack {worst:.4f} ns "
            f"at period {args.period} ns\n")
        return 1

    print(f"STA PASS: {args.name}  worst slack {worst:.4f} ns "
          f"@ {args.period} ns period")
    return 0


if __name__ == "__main__":
    sys.exit(main())
